entries.example:
char cwd[4096];
if (chdir("/tmp") == 0 && getcwd(cwd, sizeof cwd) != NULL)
    puts(cwd);

entries.syntax:
DIR *opendir(const char *path);
struct dirent *readdir(DIR *dir);
int closedir(DIR *dir);

entries.example:
DIR *d = opendir(".");
struct dirent *e;
while ((e = readdir(d)) != NULL) {
    if (!strcmp(e->d_name, ".") || !strcmp(e->d_name, "..")) continue;
    puts(e->d_name);
}
closedir(d);

